            "**Paracetamol 1 g PO QDS** as an add-on - alone it is no better than placebo in acute back pain. [NICE NG59 2016]",
            "**Tizanidine 2 mg PO at night for 3-5 days** if spasm dominates - it sedates, so give it at night and stop within the week.",
