        "Measure quadriceps wasting as thigh girth **15 cm above the joint line** against the other side - a fixed landmark makes it reproducible. [Apley 10e 2018]",
        "Watch the gait for antalgia and for a **varus thrust** - a thrust means the lateral structures no longer restrain the knee. [Apley 10e 2018]",
        "Supine: look again for effusion, wasting and fixed flexion deformity - the limb relaxes supine, so small effusions become visible. [Apley 10e 2018]",
        "**Fixed flexion deformity** - a hand should not pass under the knee if it is fully extended. [Apley 10e 2018]",
        "Assess varus or valgus deformity with the leg straight - flexion hides a coronal deformity. [Apley 10e 2018]",
        "Feel temperature with the back of the hand, comparing both knees and the thigh - warmth means inflammation or infection, not wear. [Apley 10e 2018]",
        "Feel for joint line tenderness with the knee **flexed to 90 degrees** - at 90 degrees the line is exposed and the meniscus palpable. [Apley 10e 2018]",
        "Feel the patellofemoral joint, tibial tubercle and popliteal fossa for a **Baker cyst** - a ruptured cyst mimics deep vein thrombosis. [Apley 10e 2018]",
        "**Patellar tap** detects a large effusion, the bulge or wipe test a small one - a tap needs enough fluid to float the patella. [Apley 10e 2018]",
        "Move: active then passive flexion and extension, a hand on the patella for crepitus - active first, so the patient sets the limit. [Apley 10e 2018]",
        "Record the arc - **normal is 0 to 135-140 degrees** - and any fixed flexion deformity. [Apley 10e 2018]",
        "Stability: anterior and posterior drawer at **90 degrees** - a posterior sag missed here reads as a false anterior drawer. [Apley 10e 2018]",
        "**Lachman test at 20-30 degrees** for the anterior cruciate - more sensitive than the drawer, since hamstrings cannot splint it. [Apley 10e 2018]",
        "Varus and valgus stress at **0 and 30 degrees** for the collaterals - laxity at 0 degrees means the cruciates are involved too. [Apley 10e 2018]",
        "Meniscal tests: **McMurray and Thessaly**, plus joint line tenderness - joint line tenderness is the most reliable single sign. [Apley 10e 2018]",
        "Examine the joint above - hip pain refers to the knee, so always test **hip rotation**. [Apley 10e 2018]",
        "Examine the joint below, and assess distal pulses and neurology - peripheral vascular disease changes what surgery is possible. [Apley 10e 2018]",
        "Observe a functional task - standing from a chair without the arms, walking, squatting if safe; function is the referral trigger. [Apley 10e 2018]",
        "Say the sequence aloud in the exam - look, feel, move, special tests, joint above and below, function.",
