        "An early intra-articular steroid injection given in the painful phase, combined with exercise, provides the best short and medium-term pain relief and return of range, and the combination outperforms either component alone. Immobilisation in a sling is actively harmful because it accelerates capsular contracture, which is one of the recognised causes of secondary capsulitis in the first place. Manipulation under anaesthesia is reserved for disabling restriction persisting after 6-9 months of proper conservative treatment and carries risks of humeral fracture, dislocation and cuff tear. Prolonged high-dose oral steroid is not recommended, offers no advantage over the targeted intra-articular route and would derail glycaemic control, and aggressive end-range stretching during the freezing phase increases pain and prolongs the illness.",
