        "Indian disease runs about a decade younger - **peak bone mass is lower and hip fractures occur 10-20 years earlier**. [ISBMR 2023]",
        "**About 50 million Indians have osteoporosis or low bone mass**, and 20% of women over 50 - so case-finding, not screening everyone. [ISBMR 2023]",
        "**One in three women and one in five men over 50** will sustain an osteoporotic fracture - which makes it a lifetime risk, not an event. [NOGG 2021]",
