        "**Non-modifiable risks: age, female sex, and menopause before 45** - oestrogen withdrawal removes the brake on osteoclasts. [NOGG 2021]",
        "**A body mass index under 19** and a parental hip fracture both raise risk independently - low mass means low peak bone mass. [NOGG 2021]",
        "A previous fragility fracture is the single strongest predictor of the next - which is why every fracture triggers assessment. [NOGG 2021]",
        "Asian and Caucasian ethnicity carry higher risk than African ancestry at the same age - peak bone mass differs between them. [NOGG 2021]",
