        "**ESR and CRP are normal in up to 40%, so a normal CRP does not exclude the disease.** [ASAS 2023]",
        "Send a complete blood count, and rheumatoid factor and anti-CCP to demonstrate seronegativity. [ASAS 2023]",
        "HLA-B27 is ordered as a supporting test, never as the test that makes the diagnosis. [ASAS 2023]",
        "**An anteroposterior radiograph of the pelvis for the sacroiliac joints is the single most useful film.** [ASAS 2023]",
        "**Radiographic sacroiliitis evolves through blurring of the joint margin, then erosions giving a pseudo-widened joint.** [Apley 10e 2018]",
        "Sclerosis follows, then narrowing, and finally ankylosis of the joint. [Apley 10e 2018]",
        "**Spinal changes: shiny corners (Romanus lesion), squaring of vertebral bodies, then syndesmophytes.** [Apley 10e 2018]",
        "**The bamboo spine with ossified ligaments is the end stage** and fractures like a long bone. [Apley 10e 2018]",
        "**MRI of the sacroiliac joints with STIR sequences detects bone marrow oedema years before radiographic change.** [ASAS 2023]",
        "**MRI is the test that diagnoses non-radiographic axial spondyloarthritis** - order it when suspicion is high and the pelvic film is normal. [ASAS 2023]",
        "**Physiotherapy and daily exercise are the cornerstone and matter more than any drug.** [ASAS 2023]",
        "Prescribe spinal extension, posture, deep breathing and chest expansion exercises, with hydrotherapy where available. [ASAS 2023]",
        "Advise sleeping supine on a firm bed with one thin pillow to preserve extension. [ASAS 2023]",
